import { useState, useCallback, useMemo } from "react";
import styled from 'styled-components';
import { StudioProApi } from "@mendix/extensions-api";

import { AppSelectorNoVersionIcon } from "@mendix/ide-icons/AppSelectorNoVersionIcon";
import { EditIcon } from "@mendix/ide-icons/EditIcon";
import { MicroflowIcon } from "@mendix/ide-icons/MicroflowIcon";
import { PageIcon } from "@mendix/ide-icons/PageIcon";
import { ErrorIcon } from "@mendix/ide-icons/ErrorIcon";
import { SyncIcon } from "@mendix/ide-icons/SyncIcon";
import { ResizableTableContainer, type Selection } from '@mendix/ide-ui-components/table/Table';
import { ToolbarButton } from "@mendix/ide-ui-components/toolbar/ToolbarButton";

import { Agent } from "../../types/agent";
import { ToolValidationState } from "../../types/tool";
import { handleEditTool, handleDeleteTool } from "./agentHandlers";

import FormDivider from "../components/FormDivider";
import Table, { useTableSorting } from "../components/Table";
import TextWithIcon from "../components/TextWithIcon";
import { Checkbox } from "@mendix/ide-ui-components/checkbox/Checkbox";
import IconWrapper from "../components/Icon";

const StyledCheckbox = styled(Checkbox)`
    pointer-events: auto;
    position: relative;
    z-index: 10;
`;

interface ToolsTableProps {
    agent: Agent;
    studioPro: StudioProApi;
    componentName: string;
    updateStudioProDocument: (agent: Agent) => Promise<void>;
    onAgentChange: (updatedAgent: Agent) => void;
    toolValidations: Map<string, ToolValidationState>;
}

const ToolsTable: React.FC<ToolsTableProps> = ({
    agent,
    studioPro,
    componentName,
    updateStudioProDocument,
    onAgentChange,
    toolValidations
}) => {
    const [selectedToolKeys, setSelectedToolKeys] = useState<Selection>([]);

    // Prepare the table data with proper structure for sorting
    const tableData = useMemo(() => {
        if (!agent.tools) return [];
        return agent.tools.map((tool, index) => ({
            id: tool.id ?? String(index),
            enabled: tool.enabled,
            name: tool.name,
            description: tool.description || "",
            tool: tool.microflow || ""
        }));
    }, [agent.tools]);

    // Sorting hook to manage sort state
    const { items, sortProps } = useTableSorting(tableData);

    const getValidationIcon = useCallback((toolId: string) => {
        const state = toolValidations.get(toolId);
        if (state === 'invalid') {
            return <IconWrapper icon={<ErrorIcon title="Microflow invalid" />} />;
        } else if (state === 'syncing') {
            return <IconWrapper icon={<SyncIcon title="Validating..." />} />;
        }
        return null;
    }, [toolValidations]);

    const addTool = useCallback(async () => {
        const updatedAgent = await handleEditTool(studioPro, componentName, agent, updateStudioProDocument);
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [studioPro, componentName, agent, updateStudioProDocument, onAgentChange]);

    const editTool = useCallback(async () => {
        if (selectedToolKeys.length === 0 || !agent.tools) {
            return;
        }
        const selectedToolId = selectedToolKeys[0] as string;
        const updatedAgent = await handleEditTool(studioPro, componentName, agent, updateStudioProDocument, selectedToolId);
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [studioPro, componentName, agent, updateStudioProDocument, onAgentChange, selectedToolKeys]);

    const deleteTool = useCallback(async () => {
        if (selectedToolKeys.length === 0 || !agent.tools) {
            return;
        }
        const selectedToolId = selectedToolKeys[0] as string;
        const updatedAgent = await handleDeleteTool(studioPro, agent, updateStudioProDocument, selectedToolId);
        if (updatedAgent) {
            onAgentChange(updatedAgent);
        }
    }, [agent, updateStudioProDocument, onAgentChange, selectedToolKeys]);

    const setEnabled = useCallback(async (toolId: string, isEnabled: boolean) => {
        if (!agent.tools) {
            return;
        }
        const updatedTools = agent.tools.map(tool =>
            (tool.id ?? '') === toolId ? { ...tool, enabled: isEnabled } : tool
        );
        const updatedAgent = { ...agent, tools: updatedTools };
        updateStudioProDocument(updatedAgent);
        onAgentChange(updatedAgent);
    }, [agent.tools, updateStudioProDocument, onAgentChange]);

    return (
        <FormDivider label="Tools">
            <ResizableTableContainer>
                <Table
                    ariaLabel="Tools table"
                    columns={[
                        { id: "validation", minWidth: 24, defaultWidth: 24, maxWidth: 24 },
                        { id: "enabled", caption: "Active", isControl: true, minWidth: 63, defaultWidth: 63, maxWidth: 63, allowsSorting: true, alignContents: "center" },
                        { id: "name", caption: "Name", isRowHeader: true, resizable: true, allowsSorting: true },
                        { id: "description", caption: "Description", resizable: true, allowsSorting: true },
                        { id: "tool", caption: "Tool", resizable: true, allowsSorting: true }
                    ]}
                    data={items.map(item => [
                        getValidationIcon(item.id),
                        <StyledCheckbox
                            aria-label="Enabled"
                            isSelected={item.enabled}
                            onChange={(isEnabled) => setEnabled(item.id, isEnabled)}
                        />,
                        item.name,
                        item.description,
                        <TextWithIcon
                            icon={<MicroflowIcon />}
                            text={item.tool}
                        />
                    ])}
                    rowKey={(_, index) => items[index]?.id ?? String(index)}
                    rowOpacity={(index) => items[index]?.enabled ? 1 : 0.5}
                    selectionType="row"
                    selectionMode="single"
                    selectedKeys={selectedToolKeys}
                    onDoubleClick={editTool}
                    onSelectionChange={setSelectedToolKeys}
                    {...sortProps}
                    toolbarLeft={<>
                        <ToolbarButton
                            icon={<PageIcon />}
                            label="New"
                            aria-label="Add new tool"
                            tooltip="Add new tool"
                            onPress={addTool}
                        />
                        <ToolbarButton
                            icon={<EditIcon />}
                            label="Edit"
                            aria-label="Edit selected tool"
                            onPress={editTool}
                            tooltip="Edit selected tool"
                            isDisabled={selectedToolKeys.length === 0}
                        />
                        <ToolbarButton
                            icon={<AppSelectorNoVersionIcon />}
                            label="Delete"
                            aria-label="Delete selected tool"
                            onPress={deleteTool}
                            tooltip="Delete selected tool"
                            isDisabled={selectedToolKeys.length === 0}
                        />
                    </>}
                />
            </ResizableTableContainer>
        </FormDivider>
    );
};

export default ToolsTable;
